<template><div class="page power-page">
 <div class="page-header"><div><div class="page-title">配电拓扑管理</div><div class="subtitle">按供电关系自定义多级节点，自动生成配电拓扑图</div></div><el-button v-if="canEdit" type="primary" @click="openCreate()">新增根节点</el-button></div>
 <el-tabs v-model="tab"><el-tab-pane label="层级维护" name="manage"><div class="manage-grid">
  <div class="tree-card"><el-empty v-if="!tree.length" description="暂无配电节点"/><el-tree v-else :data="tree" node-key="id" default-expand-all :expand-on-click-node="false"><template #default="{data}"><div class="tree-row"><span><el-tag size="small" :type="tagType(data.nodeType)">{{data.nodeTypeName}}</el-tag> {{data.nodeCode}} · {{data.nodeName}}</span><span v-if="canEdit" class="actions"><el-button link type="primary" @click.stop="openCreate(data)">添加下级</el-button><el-button link @click.stop="openEdit(data)">编辑</el-button><el-popconfirm title="只能删除没有下级的节点，确认删除？" @confirm="remove(data)"><template #reference><el-button link type="danger" @click.stop>删除</el-button></template></el-popconfirm></span></div></template></el-tree></div>
  <div class="detail-card"><template v-if="selected"><h3>{{selected.nodeCode}} · {{selected.nodeName}}</h3><el-descriptions :column="1" border><el-descriptions-item label="节点类型">{{selected.nodeTypeName}}</el-descriptions-item><el-descriptions-item label="上级开关">{{selected.switchSpecificationName||'未配置'}}</el-descriptions-item><el-descriptions-item label="额定参数">{{parameterText(selected)}}</el-descriptions-item><el-descriptions-item label="安装位置">{{selected.location||'-'}}</el-descriptions-item><el-descriptions-item label="关联铺位/设备">{{selected.stallCode||'-'}} / {{selected.platformDeviceId||'-'}}</el-descriptions-item><el-descriptions-item label="备注">{{selected.remark||'-'}}</el-descriptions-item></el-descriptions></template><el-empty v-else description="点击拓扑节点查看详情"/></div>
 </div></el-tab-pane>
 <el-tab-pane label="拓扑图" name="graph"><div class="graph-toolbar"><span>节点 {{flat.length}} 个，可横向滚动查看完整拓扑</span><el-button @click="fitGraph">回到起点</el-button></div><div ref="graphScroller" class="graph-scroll"><svg :width="graphWidth" :height="graphHeight" class="topology-svg"><g v-for="edge in edges" :key="edge.key"><path :d="edge.path" class="edge"/></g><g v-for="n in positioned" :key="n.id" class="node" :transform="`translate(${n.x},${n.y})`" @click="selectNode(n)"><rect width="190" height="82" rx="10" :class="{'disabled':n.status!==1}"/><text x="12" y="22" class="node-type">{{n.nodeTypeName}}</text><text x="12" y="45" class="node-title">{{short(n.nodeCode+' · '+n.nodeName,22)}}</text><text x="12" y="66" class="node-sub">{{short(n.switchSpecificationName||parameterText(n),25)}}</text></g></svg></div></el-tab-pane></el-tabs>
 <el-dialog v-model="visible" :title="form.id?'编辑配电节点':(form.parentId?'添加下级节点':'新增根节点')" width="650px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="上级节点"><el-tree-select v-model="form.parentId" :data="parentOptions" node-key="id" :props="{label:'displayName',children:'children'}" clearable check-strictly style="width:100%" placeholder="留空表示根节点"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="节点编码" prop="nodeCode"><el-input v-model="form.nodeCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="节点名称" prop="nodeName"><el-input v-model="form.nodeName"/></el-form-item></el-col></el-row><el-form-item label="节点类型" prop="nodeType"><el-select v-model="form.nodeType" style="width:100%"><el-option v-for="d in nodeTypes" :key="d.id" :label="d.itemLabel" :value="d.itemValue"/></el-select></el-form-item><el-form-item label="上级出线开关"><el-select v-model="form.switchSpecificationId" clearable filterable style="width:100%" placeholder="选择为该节点供电的开关型号"><el-option v-for="s in switches" :key="s.id" :label="`${s.brand||''} ${s.switchModel} · ${s.ratedCurrentA}A`" :value="s.id"/></el-select></el-form-item><el-row :gutter="12"><el-col :span="8"><el-form-item label="电压(V)"><el-input-number v-model="form.ratedVoltageV" :min="0" :precision="1"/></el-form-item></el-col><el-col :span="8"><el-form-item label="电流(A)"><el-input-number v-model="form.ratedCurrentA" :min="0" :precision="1"/></el-form-item></el-col><el-col :span="8"><el-form-item label="功率(kW)"><el-input-number v-model="form.ratedPowerKw" :min="0" :precision="2"/></el-form-item></el-col></el-row><el-form-item label="安装位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="关联铺位"><el-select v-model="form.stallId" clearable filterable style="width:100%"><el-option v-for="s in stalls" :key="s.id" :label="`${s.stallCode} · ${s.stallName}`" :value="s.id"/></el-select></el-form-item><el-form-item label="关联设备ID"><el-input v-model="form.platformDeviceId" placeholder="终端或用电设备可填写能源平台设备ID"/></el-form-item><el-row><el-col :span="12"><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item></el-col><el-col :span="12"><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0" active-text="启用"/></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox,type FormInstance}from'element-plus';import{powerTopologyApi,type PowerNode}from'@/api/power';import{dictionaryApi,powerSwitchSpecificationApi,type DictionaryItem,type PowerSwitchSpecification}from'@/api/system';import{stallApi}from'@/api/merchant';import{useUserStore}from'@/stores/user';
const tab=ref('manage'),tree=ref<PowerNode[]>([]),nodeTypes=ref<DictionaryItem[]>([]),switches=ref<PowerSwitchSpecification[]>([]),stalls=ref<any[]>([]),visible=ref(false),saving=ref(false),selected=ref<PowerNode>(),formRef=ref<FormInstance>(),graphScroller=ref<HTMLElement>();const userStore=useUserStore(),canEdit=computed(()=>userStore.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));const form=reactive<any>({});const rules={nodeCode:[{required:true,message:'请输入节点编码'}],nodeName:[{required:true,message:'请输入节点名称'}],nodeType:[{required:true,message:'请选择节点类型'}]};
const flat=computed(()=>{const out:any[]=[];const walk=(rows:PowerNode[],depth=0)=>rows.forEach(n=>{out.push({...n,depth});walk(n.children||[],depth+1)});walk(tree.value);return out});const parentOptions=computed(()=>{const copy=(rows:PowerNode[]):any[]=>rows.filter(n=>n.id!==form.id).map(n=>({id:n.id,displayName:`${n.nodeCode} · ${n.nodeName}`,children:copy(n.children||[])}));return copy(tree.value)});
const positioned=computed(()=>{let leaf=0;const out:any[]=[];const walk=(n:PowerNode,depth:number):number=>{const childXs=(n.children||[]).map(c=>walk(c,depth+1));const x=childXs.length?childXs.reduce((a,b)=>a+b,0)/childXs.length:50+leaf++*230;out.push({...n,x,y:35+depth*145});return x};tree.value.forEach(n=>walk(n,0));return out});const posMap=computed(()=>new Map(positioned.value.map(n=>[n.id,n])));const edges=computed(()=>positioned.value.filter(n=>n.parentId&&posMap.value.has(n.parentId)).map(n=>{const p:any=posMap.value.get(n.parentId);return{key:`${p.id}-${n.id}`,path:`M ${p.x+95} ${p.y+82} V ${p.y+112} H ${n.x+95} V ${n.y}`}}));const graphWidth=computed(()=>Math.max(900,...positioned.value.map(n=>n.x+230)));const graphHeight=computed(()=>Math.max(420,...positioned.value.map(n=>n.y+125)));
async function load(){tree.value=await powerTopologyApi.tree() as any;if(selected.value)selected.value=flat.value.find(n=>n.id===selected.value?.id)}async function loadOptions(){const[r1,r2,r3]:any=await Promise.all([dictionaryApi.list('POWER_NODE_TYPE' as any),powerSwitchSpecificationApi.list(),stallApi.page({pageNum:1,pageSize:500})]);nodeTypes.value=r1;switches.value=r2;stalls.value=r3.records||[]}
function reset(){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{id:0,parentId:null,nodeCode:'',nodeName:'',nodeType:'',switchSpecificationId:null,ratedVoltageV:380,ratedCurrentA:null,ratedPowerKw:null,location:'',stallId:null,platformDeviceId:'',sortOrder:0,status:1,remark:''})}function openCreate(parent?:PowerNode){reset();form.parentId=parent?.id||null;visible.value=true}function openEdit(n:PowerNode){reset();Object.assign(form,n);delete form.children;visible.value=true;selected.value=n}async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{const data={...form,parentId:form.parentId||null,switchSpecificationId:form.switchSpecificationId||null,stallId:form.stallId||null,platformDeviceId:form.platformDeviceId?.trim()||null};delete data.id;if(form.id)await powerTopologyApi.update(form.id,data);else await powerTopologyApi.create(data);visible.value=false;ElMessage.success('配电节点已保存，拓扑图已更新');await load()}finally{saving.value=false}}async function remove(n:PowerNode){await powerTopologyApi.remove(n.id);if(selected.value?.id===n.id)selected.value=undefined;ElMessage.success('节点已删除');await load()}function selectNode(n:any){selected.value=n;tab.value='manage'}function parameterText(n:any){return[n.ratedVoltageV!=null?`${n.ratedVoltageV}V`:'',n.ratedCurrentA!=null?`${n.ratedCurrentA}A`:'',n.ratedPowerKw!=null?`${n.ratedPowerKw}kW`:''].filter(Boolean).join(' / ')||'未配置额定参数'}function short(v:string,n:number){return v.length>n?v.slice(0,n)+'…':v}function tagType(t:string){return t==='TRANSFORMER'?'danger':t==='ELECTRICAL_DEVICE'?'success':t==='DISTRIBUTION_BOX'?'warning':'primary'}function fitGraph(){if(graphScroller.value){graphScroller.value.scrollLeft=0;graphScroller.value.scrollTop=0}}onMounted(async()=>{await Promise.all([load(),loadOptions()])})
</script>
<style scoped>.subtitle{font-size:13px;color:#909399;margin-top:4px}.manage-grid{display:grid;grid-template-columns:minmax(520px,2fr) minmax(300px,1fr);gap:16px}.tree-card,.detail-card,.graph-scroll{background:#fff;border-radius:8px;padding:16px;min-height:420px}.tree-row{width:100%;display:flex;justify-content:space-between;align-items:center;padding-right:10px}.actions{white-space:nowrap}.graph-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;color:#606266}.graph-scroll{overflow:auto;padding:0}.topology-svg{background-image:radial-gradient(#d9e1ec 1px,transparent 1px);background-size:18px 18px}.edge{fill:none;stroke:#7891ad;stroke-width:2}.node{cursor:pointer}.node rect{fill:#fff;stroke:#409eff;stroke-width:2;filter:drop-shadow(0 3px 4px #0002)}.node rect.disabled{fill:#f3f4f6;stroke:#a8abb2}.node-type{font-size:12px;fill:#409eff}.node-title{font-size:14px;font-weight:600;fill:#303133}.node-sub{font-size:11px;fill:#606266}@media(max-width:768px){.manage-grid{grid-template-columns:1fr}.tree-card{padding:8px;overflow:auto}.detail-card{min-height:260px}.tree-row{min-width:560px}.power-page :deep(.el-dialog){width:94%!important}.power-page :deep(.el-col){max-width:100%;flex:0 0 100%}}</style>
